  ('w-jmdict-2061640-k0', 'w-jmdict-2061640', '一年前', 'kanji', false, '{}'::text[], 0),
  ('w-jmdict-2061640-k1', 'w-jmdict-2061640', '１年前', 'kanji', false, '{}'::text[], 1),
  ('w-jmdict-2061640-r0', 'w-jmdict-2061640', 'いちねんまえ', 'kana', false, '{}'::text[], 100)
) AS v(id, word_id, form, kind, is_common, tags, sort_index)
WHERE EXISTS (SELECT 1 FROM words WHERE id = 'w-jmdict-2061640')
ON CONFLICT (id) DO NOTHING;

INSERT INTO word_senses (id, word_id, sort_index, glosses, pos, fields, misc, dialect)
SELECT v.* FROM (VALUES
  ('w-jmdict-2061640-s0', 'w-jmdict-2061640', 0, '[{"lang":"en","text":"one year ago"}]'::jsonb, ARRAY['n', 'adv']::text[], '{}'::text[], '{}'::text[], '{}'::text[])
) AS v(id, word_id, sort_index, glosses, pos, fields, misc, dialect)
WHERE EXISTS (SELECT 1 FROM words WHERE id = 'w-jmdict-2061640')
ON CONFLICT (id) DO NOTHING;
